const defaultConfig={fitWidth:72,fitHeight:56,hiddenFraction:.25,rowPitch:60,lineWidth:.5,lineExtension:8,emptyTraceLength:24,outerInset:6,firstCenterFromTop:202,screenPadding:12,numberFontSize:11,numberGap:8,leftPadding:4,minimumHitWidth:44,minimumHitHeight:44,arrivalDuration:.22,pressDuration:.06,inwardDistance:1.5,swallowDuration:.12,shiftDuration:.16,returnDuration:.18,reducedMotionDuration:.08,preferredDisplayID:null,visibleCountPreference:3,placement:'leftMiddle',placementSource:'initialRecommendation',preferredDisplayUUID:null};
const displayKeys=['fitWidth','fitHeight','hiddenFraction','rowPitch','lineWidth','lineExtension','outerInset','firstCenterFromTop','screenPadding','numberFontSize','numberGap','leftPadding','minimumHitWidth','minimumHitHeight','visibleCountPreference'];
const motionKeys=['pressDuration','inwardDistance','swallowDuration','shiftDuration','returnDuration','reducedMotionDuration'];
const limits={fitWidth:[0,256],fitHeight:[0,256],hiddenFraction:[0,.9],rowPitch:[0,Infinity],lineWidth:[0,8],lineExtension:[0,Infinity],outerInset:[0,256],firstCenterFromTop:[0,Infinity],screenPadding:[0,256],numberFontSize:[0,32],numberGap:[0,Infinity],leftPadding:[0,Infinity],minimumHitWidth:[0,256],minimumHitHeight:[0,256],arrivalDuration:[0,3],pressDuration:[0,3],inwardDistance:[0,Infinity],swallowDuration:[0,3],shiftDuration:[0,3],returnDuration:[0,3],reducedMotionDuration:[0,3],visibleCountPreference:[1,10]};
const strictlyPositive=new Set(['fitWidth','fitHeight','rowPitch','lineWidth','numberFontSize','minimumHitWidth','minimumHitHeight']);
const numericPattern=/^(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$/;
const fieldLabels={fitWidth:'微图最大宽度',fitHeight:'微图最大高度',hiddenFraction:'静止时遮挡',rowPitch:'相邻微图中心间距',lineWidth:'裂缝线宽',lineExtension:'裂缝上下延伸',outerInset:'距屏幕边缘',firstCenterFromTop:'旧版顶部绝对位置',screenPadding:'屏幕安全留白',numberFontSize:'编号字号',numberGap:'编号与微图间距',leftPadding:'微图内侧留白',minimumHitWidth:'最小点击区域宽度',minimumHitHeight:'最小点击区域高度',pressDuration:'按下反馈',inwardDistance:'按下内移',swallowDuration:'收起',shiftDuration:'下方补位',returnDuration:'返回',reducedMotionDuration:'减少动态时淡变',visibleCountPreference:'每页显示'};
const $=s=>document.querySelector(s);const app=$('#riftlet-design');
const copy=v=>JSON.parse(JSON.stringify(v));
let state,toastTimer,motionTimer,returnFocus;
function mark(){return '<span class="brandmark" aria-hidden="true"><svg viewBox="0 0 28 32" fill="none"><path d="M5 5h11c5 0 8 3 8 7s-3 7-8 7h-2l9 9h-8L5 18V5Z" fill="currentColor"/><path d="M7 2v28" stroke="var(--window)" stroke-width="2"/></svg></span>';}
